(function () {
  'use strict';
  const chunkSet = {"title":"Author's Purpose","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-authors-purpose-q0151","version":3,"contentHash":"sha256:bc6314908a04e351595dcc3da8812754cd20682269a4d2534f757fb68d5baf34","question":"Read the passage. Grade 5 developing passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. These details show that students used careful daily routines to help a garden grow. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to confuse readers about the topic","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to explain how students cared for a garden"],"correct":3,"studyAid":{"definition":"An author's purpose is the reason why they wrote a piece, usually to explain, inform, persuade, or entertain.","example":"A recipe (to explain), a news report (to inform), a fairy tale (to entertain), an advertisement (to persuade).","strategyClue":"Look at the main actions described in the passage and ask yourself: 'What is the main topic, and what is the author trying to teach me about that topic?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students cared for a garden. The text describes specific actions taken by the students, such as watering seedlings and moving shade cloth, to show the process of maintaining a healthy school garden.","incorrect":[{"choice":"to confuse readers about the topic","category":"incorrect author purpose","reason":"The author provides clear, sequential details about gardening, which is the opposite of trying to confuse the reader."},{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong text type","reason":"This text is informational rather than fictional; it focuses on real-world steps for gardening rather than a character-driven adventure story."},{"choice":"to list unrelated facts without a main point","category":"missing main idea","reason":"The facts provided are all related to the central theme of gardening, and they work together to explain a specific process."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":151,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0152","version":3,"contentHash":"sha256:4310a7813a6f79820094669b7bd9c3f59b55d740dc65d50f897c373faaceee08","question":"Read the passage. Grade 5 developing passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. These details show that student volunteers organized books and labels to make the library easier to use. The author presents the steps and results so readers understand how the process works.\n\nWhich clue best shows that the author wants to explain?","choices":["They sorted returned books by call number before placing them on shelves.","The cafeteria served tomato soup on Thursday.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":0,"studyAid":{"definition":"Expository writing explains a process or topic by providing clear, step-by-step details and examples to show how something is done.","example":"A recipe (first, boil water; then, add pasta), a set of instructions for a game, or a summary of how a project was finished.","strategyClue":"Look for a sentence in the text that describes a specific, sequential action that helps the reader follow the 'how' or 'why' of the topic.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This choice describes a specific action, which helps the reader understand the chronological steps taken to complete the task.","incorrect":["",{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This sentence provides details about a cafeteria, which is unrelated to the library or the author's purpose of explaining how the library was organized."},{"choice":"The passage avoids the topic after the first sentence.","category":"inaccurate claim","reason":"This is incorrect because the passage continues to provide specific examples, such as sorting books and making labels, to support the main topic."},{"choice":"The passage gives no examples or details.","category":"missing evidence","reason":"The passage actually provides several clear examples, such as the specific way books were sorted and the types of labels created, to explain the process."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":152,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0153","version":3,"contentHash":"sha256:1f67d1591b18939ee31c2cb22a4e20794ade72ab8c8416793a1a14b7542805ee","question":"Read the passage. Grade 5 developing passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. These details show that a science club collected and reused rainwater to care for plants. The author presents the steps and results so readers understand how the process works.\n\nWhich audience would most likely find this passage useful?","choices":["readers looking for a fantasy story with magic","readers who want to learn about the topic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":1,"studyAid":{"definition":"To identify a target audience, look at the text's purpose: is it to inform, entertain, or persuade? Informational texts teach readers about facts, processes, or real-world events.","example":"A guide on fixing a bike is for people who want to learn mechanics; a mystery novel is for people who want to be entertained by a story.","strategyClue":"Identify the main topic of the text first. Then, ask yourself: 'Who would benefit from knowing this information?' Look for the choice that connects directly to the information presented in the passage.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information about rainwater collection, which is a process used for plant care. This matches the interests of someone seeking knowledge on a scientific or practical subject.","incorrect":[{"choice":"readers looking for a fantasy story with magic","category":"incorrect genre","reason":"The passage describes real-world science and gardening. It does not contain the made-up creatures or magical events found in a fantasy story."},"",{"choice":"readers studying a recipe for dessert","category":"mismatched topic","reason":"This passage is about collecting rainwater for plants. A recipe for dessert would focus on baking, ingredients, and kitchen instructions rather than environmental science."},{"choice":"readers trying to learn a new song","category":"mismatched purpose","reason":"The passage explains a process involving barrels and roofs. It lacks musical notation, lyrics, or rhythm, which are what a reader looking for a song would expect."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":153,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0154","version":3,"contentHash":"sha256:0818e3fe3cea7cee3726445111b53a45fd4547b8eb05312f1c97e191ff60de7f","question":"Read the passage. Grade 5 developing passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. These details show that student reporters gathered facts and published school news. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to list unrelated facts without a main point","to tell a made-up adventure with a surprising ending","to explain how students made a newspaper","to confuse readers about the topic"],"correct":2,"studyAid":{"definition":"An author's purpose is the reason they wrote a text, such as to inform, to explain, to describe, or to entertain.","example":"A recipe explains how to bake; a biography informs about a person's life; a fantasy story entertains the reader.","strategyClue":"Look at the actions described in the text and ask yourself: Is the author telling a story, teaching me how to do something, or sharing facts about a specific topic?","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students made a newspaper. The author describes a sequence of events—interviewing, writing, checking facts, and publishing—to help the reader understand the process the students followed.","incorrect":[{"choice":"to list unrelated facts without a main point","category":"lack of coherence","reason":"The facts provided in the passage are not unrelated; they all focus on the specific steps taken to create the newspaper, which serves as a clear main point."},{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect text type","reason":"This passage is informative rather than fictional. It describes real-world actions taken by reporters rather than using a plot with an adventure or a surprise twist."},"",{"choice":"to confuse readers about the topic","category":"illogical purpose","reason":"The author's goal is to inform and clarify. Using clear language to detail the steps of a process is the opposite of trying to confuse the reader."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":154,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0155","version":3,"contentHash":"sha256:fb9f5a4883ee51a52bd412d5fa617a56a9c5cdd99b7685b1ded8e14c04c717fa","question":"Read the passage. Grade 5 developing passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. These details show that families cleaned litter from the beach and encouraged visitors to keep it clean. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The passage gives no examples or details.","The town band played a concert in the park.","The passage avoids the topic after the first sentence.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line."],"correct":3,"studyAid":{"definition":"Persuasive writing uses reasons and specific examples to convince the reader that an idea is important or that a specific action should be taken.","example":"Persuasive sentence: 'Everyone should help clean the park to make it safer for animals.' vs. Informational sentence: 'There are four trash cans in the park.'","strategyClue":"Look for the sentence that describes an action or result that makes the reader feel the activity is good, helpful, or necessary to solve a problem.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides specific evidence of a positive action taken by the families, which supports the author's argument that people should participate in cleanup efforts.","incorrect":[{"choice":"The passage gives no examples or details.","category":"ignoring textual evidence","reason":"The passage actually includes specific details, such as the ten bags of trash and the signs posted by volunteers, which show the author is building a case to support cleaning up the beach."},{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This information is not mentioned in the text and has nothing to do with the author's point about cleaning up the beach or solving community problems."},{"choice":"The passage avoids the topic after the first sentence.","category":"misreading the text","reason":"The entire passage stays focused on the litter cleanup, the volunteers, and the reason why this work is important for the community."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":155,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0156","version":3,"contentHash":"sha256:3ceb7a7535e9d79f1707143df14a895fa234b785f0d9b4a08ffeb7b3cf5c3a24","question":"Read the passage. Grade 5 developing passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. These details show that a safety officer taught students important bike safety habits. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich audience would most likely find this passage useful?","choices":["readers who want to learn about the topic","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":0,"studyAid":{"definition":"To determine the target audience of a text, look for the author's purpose: are they explaining, describing, or persuading the reader about a specific topic?","example":"A cookbook is for people wanting to cook; a map is for people wanting to find their way; a news article is for people wanting to know about current events.","strategyClue":"Identify the main topic of the passage first, then match that topic to the goal of the reader. If the text explains 'how-to' or provides facts, look for the option that describes someone seeking that specific type of information.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information and advice about bike safety, making it most useful for people seeking to gain knowledge or learn how to perform a task safely.","incorrect":["",{"choice":"readers looking for a fantasy story with magic","category":"wrong genre","reason":"This passage is non-fiction and deals with real-life safety practices, not imaginary worlds or magical elements found in fantasy stories."},{"choice":"readers studying a recipe for dessert","category":"mismatched topic","reason":"The text focuses on bicycle safety and community habits, which does not provide ingredients or instructions for cooking or baking a dessert."},{"choice":"readers trying to learn a new song","category":"mismatched purpose","reason":"There is no mention of musical notes, lyrics, or rhythms in this text; it is strictly an informative piece about public safety."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":156,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0157","version":3,"contentHash":"sha256:d2210751d299fd946b1c7d0dff4d0d1d555507c109d06af293b59bc5cf50e027","question":"Read the passage. Grade 5 developing passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. These details show that transportation planners improved bus service so people could reach useful places. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to tell a made-up adventure with a surprising ending","to explain how new bus routes helped a neighborhood","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":1,"studyAid":{"definition":"An author's purpose is the reason they wrote a text, such as to explain how something works, describe a person or place, or tell a story.","example":"An informational book on space (to explain), a fairy tale (to entertain), a persuasive speech (to convince).","strategyClue":"Look for the common theme in the details provided. Ask yourself: 'What is the main problem being discussed, and what result does the author show?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how new bus routes helped a neighborhood. The text focuses on the actions planners took and the positive results for the community, which directly illustrates the cause and effect of the bus route improvements.","incorrect":[{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect text type","reason":"This is a factual, informative passage. It does not use story elements like characters, dialogue, or a plot twist that would be found in a fiction adventure."},"",{"choice":"to list unrelated facts without a main point","category":"missing main idea","reason":"The sentences are related because they all focus on bus service. A list of random facts would not connect together to explain a single process or improvement."},{"choice":"to confuse readers about the topic","category":"incorrect writing goal","reason":"Authors write to share information clearly, not to confuse the reader. The passage provides organized details to help the reader understand a specific process."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":157,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0158","version":3,"contentHash":"sha256:b6bc5b16e4aac859c8ae1d798c46309060747f7c0017b53bf5c0f572840eb3c3","question":"Read the passage. Grade 5 developing passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. These details show that actors and crew members cooperated to get a play ready. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich clue best shows that the author wants to describe?","choices":["The passage avoids the topic after the first sentence.","A math poster showed different kinds of triangles.","Actors practiced lines while stage crew members painted scenery and tested lights.","The passage gives no examples or details."],"correct":2,"studyAid":{"definition":"Descriptive writing uses specific actions, sensory details, and clear examples to help a reader visualize a scene or understand a topic better.","example":"General: 'He cleaned his room.' Descriptive: 'He scrubbed the dusty shelves and organized his colorful books by height.'","strategyClue":"Scan the text for sentences that describe specific jobs or actions rather than general statements; look for words that show what characters are actually doing.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence provides specific, vivid details about what each person was doing, which helps the reader visualize the process of preparing a play.","incorrect":[{"choice":"The passage avoids the topic after the first sentence.","category":"Incorrect comprehension claim","reason":"This is incorrect because the entire paragraph stays focused on the play preparations by listing specific tasks performed by different crew members."},{"choice":"A math poster showed different kinds of triangles.","category":"Irrelevant information","reason":"This choice is irrelevant to the passage, as the text is entirely about theater production and contains no mention of math or shapes."},"",{"choice":"The passage gives no examples or details.","category":"Incorrect factual summary","reason":"The passage is actually full of details, such as painting scenery, testing lights, and fixing a tangled rope, which help the reader form a clear picture."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":158,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0159","version":3,"contentHash":"sha256:c27635d235cec3e38e3422678d5f76340f60977ee352331e885b435be77e4873","question":"Read the passage. Grade 5 developing passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. These details show that cafeteria food scraps were collected and turned into compost for flowers. The author presents the steps and results so readers understand how the process works.\n\nWhich audience would most likely find this passage useful?","choices":["readers trying to learn a new song","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers who want to learn about the topic"],"correct":3,"studyAid":{"definition":"The audience for a text is the group of people for whom the information is intended based on the topic and the way the author presents it.","example":"A guide on how to build a birdhouse is for people interested in building/nature. A story about a dragon is for people interested in fiction.","strategyClue":"Identify the main topic of the passage first, then ask yourself: 'Who would benefit from knowing this specific information?' Match that person to the choice.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual, step-by-step information about composting, which serves the purpose of explaining a process to those interested in learning how it works.","incorrect":[{"choice":"readers trying to learn a new song","category":"mismatched instructional purpose","reason":"This passage explains a scientific process, not lyrics or musical notes. Learning a song requires a different type of content, such as sheet music or rhythm patterns."},{"choice":"readers looking for a fantasy story with magic","category":"mismatched genre type","reason":"The passage describes real-world actions like composting food scraps. It lacks the imaginary characters, settings, and magical elements required for a fantasy story."},{"choice":"readers studying a recipe for dessert","category":"mismatched informational content","reason":"While the passage mentions 'food,' it describes turning scraps into dirt for plants. It does not provide ingredients or instructions for cooking something to eat."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":159,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0160","version":3,"contentHash":"sha256:b116cd53fe30bf444ce73febca44061dc446c26991bf1619f8f6aefa5b9405e5","question":"Read the passage. Grade 5 developing passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. These details show that science students recorded weather measurements and used them to find patterns. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to explain how students studied weather","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":0,"studyAid":{"definition":"An author's purpose is the reason they wrote a text, usually to inform, persuade, entertain, or explain a process.","example":"An encyclopedia entry informs (facts about lions); a storybook entertains (a lion’s day at the zoo); a how-to guide explains (how to draw a lion).","strategyClue":"Look at the beginning and the end of the passage to identify the main topic, then ask yourself: 'Is the author telling a story, giving an opinion, or showing how something happens?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students studied weather. The passage focuses on the specific steps the students took—tracking patterns and recording measurements—to demonstrate a scientific process.","incorrect":["",{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect text type","reason":"This is a factual, scientific report, not a fictional story or adventure tale. There is no plot, conflict, or surprising twist involved."},{"choice":"to list unrelated facts without a main point","category":"lacks logical connection","reason":"The facts in the passage are all related to a central theme—weather tracking. They work together to show the reader a complete process."},{"choice":"to confuse readers about the topic","category":"contradicts author intent","reason":"The author uses clear descriptions and a logical sequence of events specifically to help the reader understand the topic, not to make it confusing."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":160,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0161","version":3,"contentHash":"sha256:ea92e7b92ca90fd364814d2e1d8b22158b601af40ce2c7a1d0f58364ccc8c876","question":"Read the passage. Grade 5 developing passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. These details show that a recycling team used bins and reminders to reduce paper waste. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The nurse checked the first-aid supplies after lunch.","They placed blue bins in classrooms and reminded students to use both sides of paper.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":1,"studyAid":{"definition":"Persuasive writing uses evidence, facts, and reasons to convince the reader to agree with an opinion or support a specific action.","example":"Opinion: 'We should walk to school.' Evidence: 'Walking reduces pollution and gives us exercise.'","strategyClue":"Look for the sentence that provides a concrete fact or specific action taken to address the problem the author is arguing about.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They placed blue bins in classrooms and reminded students to use both sides of paper. This choice provides specific evidence of actions taken to solve a problem, which supports the author's argument that recycling efforts are effective.","incorrect":[{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This information is not part of the passage and has nothing to do with the author's argument about recycling."},"",{"choice":"The passage avoids the topic after the first sentence.","category":"incorrect text analysis","reason":"The passage continues to discuss recycling and provides specific examples throughout, so this claim is false."},{"choice":"The passage gives no examples or details.","category":"ignoring textual evidence","reason":"The passage provides specific details, such as blue bins and using both sides of paper, which serve as evidence for the author's point."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":161,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0162","version":3,"contentHash":"sha256:ea568de5d2f808f2487a87b1904604218f31a343bbad60a14004badfc460f99c","question":"Read the passage. Grade 5 developing passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. These details show that museum workers created an exhibit that helped visitors learn local history. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["readers studying a recipe for dessert","readers looking for a fantasy story with magic","readers who want to learn about the topic","readers trying to learn a new song"],"correct":2,"studyAid":{"definition":"To identify the target audience, determine the author's purpose: is the text intended to inform, entertain, or persuade?","example":"A textbook informs students about history; a comic book entertains; a letter to the editor persuades.","strategyClue":"Look at the main subject of the passage—in this case, museum exhibits and history—and ask yourself what kind of information that topic provides. Match that information to the goals of the reader.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage describes a museum exhibit about local history, which provides factual information, memories, and details that help readers learn about the past.","incorrect":[{"choice":"readers studying a recipe for dessert","category":"mismatched instructional purpose","reason":"This passage describes historical museum items rather than ingredients, measurements, or cooking instructions needed for a dessert."},{"choice":"readers looking for a fantasy story with magic","category":"incompatible genre choice","reason":"The passage focuses on real historical artifacts like old tools and photographs; it does not contain fictional characters, mythical creatures, or magical plot elements."},"",{"choice":"readers trying to learn a new song","category":"unrelated content type","reason":"While the exhibit contains audio recordings of elders, it is not a musical score or song lyrics; it provides historical context, not a melody to learn."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":162,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0163","version":3,"contentHash":"sha256:a99b0e4a92da33fea41919b85c6e87fb25897423fe692cbca9da2fba8bdb1151","question":"Read the passage. Grade 5 developing passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. These details show that club members tested a robot, changed its code, and used notes to improve it. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to confuse readers about the topic","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to explain how testing improved a robot"],"correct":3,"studyAid":{"definition":"An author's purpose is the main reason why they write a text, such as to inform, explain, describe, or persuade.","example":"An article explaining how a volcano erupts (inform/explain), a story about a dragon (entertain), an essay arguing for recess (persuade).","strategyClue":"Look for a repeating topic in the text and ask yourself: 'Does this paragraph tell me a story, or does it explain how something was done or why it happened?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how testing improved a robot. The passage focuses on the specific steps the club members took—testing, coding, and note-taking—to achieve a successful result with their robot.","incorrect":[{"choice":"to confuse readers about the topic","category":"incorrect author purpose","reason":"Authors write to share information, not to confuse. The passage provides clear details about how the club improved their project."},{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong text type","reason":"This is an informational passage, not a story. It describes a logical process rather than a fictional plot with characters or a twist ending."},{"choice":"to list unrelated facts without a main point","category":"lacks central theme","reason":"The facts in this passage are all related to one main point: the process of improving a robot through testing and adjustments."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":163,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0164","version":3,"contentHash":"sha256:0b77e8af1860c6623705b8acd1d5263dadc3c7a3e52faab719f5b121392825b1","question":"Read the passage. Grade 5 developing passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. These details show that school leaders made breakfast easier for busy students to get. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The cart offered fruit, yogurt, and whole-grain muffins near the front door.","The science lab received new magnifying glasses.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":0,"studyAid":{"definition":"Persuasive writing expresses an opinion and uses facts, examples, or reasons to convince the reader that the topic is important or positive.","example":"Persuasive: 'We should plant more trees because they clean our air.' Not Persuasive: 'There are five trees in the park.'","strategyClue":"Look for a sentence that provides a specific example of why a program is helpful or good for a community; persuasive authors use these details to build their case.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The cart offered fruit, yogurt, and whole-grain muffins near the front door. This clue highlights a positive action taken to help students, which supports the author's argument that the breakfast program is a beneficial community effort.","incorrect":["",{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information provided","reason":"This detail is not mentioned in the passage and does not help explain why the breakfast program is a good idea."},{"choice":"The passage avoids the topic after the first sentence.","category":"factual inaccuracy","reason":"The entire passage focuses on the breakfast cart, showing the author clearly continues to discuss the topic to make their point."},{"choice":"The passage gives no examples or details.","category":"misreading of text","reason":"The passage provides specific examples like fruit, yogurt, and muffins to illustrate how the school is solving a problem."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":164,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0165","version":3,"contentHash":"sha256:25ac413470d0d3d3140129d0f940fa4bda0b0b27e31f8740a1d4dbfe90d5cd29","question":"Read the passage. Grade 5 developing passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. These details show that park rangers marked a trail so visitors could navigate and learn. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["readers looking for a fantasy story with magic","people who care about outdoor spaces","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":1,"studyAid":{"definition":"Identifying the target audience means figuring out who would benefit from or enjoy the information provided in a text.","example":"A guide on fixing a leaky sink is for homeowners; a book about space exploration is for science fans.","strategyClue":"Look at the specific nouns and verbs in the passage. Ask yourself, 'Is this information about entertainment, instruction, or a specific hobby?' Match those topics to the group of people most likely to seek them out.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: people who care about outdoor spaces. The passage provides descriptive details about park features like trails, trees, and benches, which are relevant to hikers, nature enthusiasts, and those interested in park maintenance.","incorrect":[{"choice":"readers looking for a fantasy story with magic","category":"wrong genre","reason":"This passage is factual and descriptive, not imaginative or magical. It describes real-world activities done by park rangers rather than a story about sorcery or imaginary realms."},"",{"choice":"readers studying a recipe for dessert","category":"wrong instructional content","reason":"A recipe would list ingredients and steps for cooking. This passage focuses on park navigation and scenery, not on how to bake or prepare food."},{"choice":"readers trying to learn a new song","category":"wrong subject matter","reason":"The passage contains no musical notes, lyrics, or instructions on how to sing. It focuses on the physical environment and amenities of a park trail."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":165,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0166","version":3,"contentHash":"sha256:043e85ec2ff0d3a1d4d12170ba98256c244738e0752e0aecae27e4c544acdda4","question":"Read the passage. Grade 5 challenge passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. Because the passage connects actions with results, readers can see why daily care helped the school garden grow well. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to list unrelated facts without a main point","to tell a made-up adventure with a surprising ending","to explain how students cared for a garden","to confuse readers about the topic"],"correct":2,"studyAid":{"definition":"The author's purpose is the reason why an author writes a text. Common purposes include to inform (explain), to persuade (convince), or to entertain (storytelling).","example":"An encyclopedia entry informs (facts), a mystery book entertains (story), and a commercial persuades (opinion).","strategyClue":"Look at the actions described in the passage and ask yourself: 'Is the author telling me a story, trying to make me think a certain way, or explaining how something is done?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students cared for a garden. The text explicitly describes the specific actions students took (watering, recording growth, moving shade cloth) to keep the garden healthy, which demonstrates the process of garden care.","incorrect":[{"choice":"to list unrelated facts without a main point","category":"disorganized information error","reason":"The sentences are not unrelated; they all focus on the theme of garden maintenance and follow a clear, logical sequence of actions and results."},{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong text type","reason":"This passage is informative rather than fictional. It does not contain characters in a plot, conflict, or a surprising climax typical of an adventure story."},"",{"choice":"to confuse readers about the topic","category":"purpose mismatch","reason":"Authors write to clarify topics, not to confuse readers. The text uses clear details about daily tasks to help the reader understand the process of growing plants."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":166,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0167","version":3,"contentHash":"sha256:1aab00ae69b31c1ece9eaa3afe57589f01b97c9ded76fa75f0a89316486fdda0","question":"Read the passage. Grade 5 challenge passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. Because the passage connects actions with results, readers can see why student helpers organized the library so readers could find books faster. The author presents the steps and results so readers understand how the process works.\n\nWhich clue best shows that the author wants to explain?","choices":["The passage gives no examples or details.","The cafeteria served tomato soup on Thursday.","The passage avoids the topic after the first sentence.","They sorted returned books by call number before placing them on shelves."],"correct":3,"studyAid":{"definition":"Expository writing explains a process, idea, or event by providing specific steps, facts, or logical connections that help the reader understand how or why something happens.","example":"To explain how to bake: 'First, preheat the oven to 350 degrees. Next, mix the flour and sugar in a large bowl.'","strategyClue":"Look for sentences that describe a sequence of actions (like 'first,' 'next,' or 'before') or explain the reason why something was done.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This sentence provides a specific, step-by-step detail of the process being explained, which demonstrates the author's intent to show how the library was organized.","incorrect":[{"choice":"The passage gives no examples or details.","category":"factual error","reason":"The passage actually provides several clear details, such as sorting by call number and making shelf labels, which helps explain the library organization process."},{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This information is not found in the text and does not relate to the author's purpose of explaining how library helpers improved the library."},{"choice":"The passage avoids the topic after the first sentence.","category":"misinterpretation of structure","reason":"The passage continues to build on the topic throughout, offering examples of how the students helped and why those actions mattered to the readers."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":167,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0168","version":3,"contentHash":"sha256:cd8317e83732505003c364a1f04dc302619b3b64cae15da5942771791b15e906","question":"Read the passage. Grade 5 challenge passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. Because the passage connects actions with results, readers can see why a rain barrel helped the club save water for plants. The author presents the steps and results so readers understand how the process works.\n\nWhich audience would most likely find this passage useful?","choices":["readers who want to learn about the topic","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":0,"studyAid":{"definition":"To determine the purpose and audience of a text, identify the main topic and look for clues that show whether the author intends to inform, persuade, or entertain.","example":"An informative article about how bees make honey is for someone learning about nature, while a story about a talking bear is for someone looking for entertainment.","strategyClue":"Ask yourself: 'Is the text explaining how to do something or describing a real-life process?' Look for keywords like 'steps,' 'results,' and 'how' to identify instructional or informative content.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information about collecting rainwater and explains the cause-and-effect relationship between rain barrels and water conservation, which serves an educational purpose.","incorrect":["",{"choice":"readers looking for a fantasy story with magic","category":"wrong genre purpose","reason":"Fantasy stories involve imaginary creatures and magic. This passage is non-fiction and based on real-world actions like collecting rainwater."},{"choice":"readers studying a recipe for dessert","category":"mismatched instructional topic","reason":"Recipes focus on cooking ingredients and food preparation. This text focuses on gardening and environmental conservation, which are unrelated to desserts."},{"choice":"readers trying to learn a new song","category":"wrong media format","reason":"Songs rely on rhythm and melody. This passage provides a technical explanation of a process rather than lyrics or musical instructions."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":168,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0169","version":3,"contentHash":"sha256:b48301064b6ab32a63bbf081d5d506686545fd8d108eca33e59d3dcb2ff9a6c5","question":"Read the passage. Grade 5 challenge passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. Because the passage connects actions with results, readers can see why the class newspaper gave students a careful way to share school news. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to tell a made-up adventure with a surprising ending","to explain how students made a newspaper","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":1,"studyAid":{"definition":"An author's purpose is their reason for writing: to inform (explain), to persuade, or to entertain.","example":"A recipe explains how to bake a cake. A fairy tale entertains with a story. An advertisement tries to persuade you to buy a toy.","strategyClue":"Identify the 'what' and 'why' of the text by summarizing the events in one sentence, then ask if the author is telling a story, describing a process, or trying to convince you of an idea.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students made a newspaper. The passage explicitly describes the steps students took—interviewing, writing, and checking facts—and links these actions to the result of creating a successful school newspaper.","incorrect":[{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect text type","reason":"The passage provides factual steps about creating a newspaper; it is not a fictional story with plot twists or a surprising climax."},"",{"choice":"to list unrelated facts without a main point","category":"missing main idea","reason":"The facts in the passage are all closely related to the process of making a newspaper, and the entire passage is organized around this single, clear goal."},{"choice":"to confuse readers about the topic","category":"misunderstanding author intent","reason":"The author clearly explains each step, making the process easy to understand rather than confusing."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":169,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0170","version":3,"contentHash":"sha256:6e77750ac9e41c3f11ae9ea089b5129e789fd04aaa75ab121ba88508336aa159","question":"Read the passage. Grade 5 challenge passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. Because the passage connects actions with results, readers can see why the cleanup protected the beach by removing harmful litter. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The passage avoids the topic after the first sentence.","The town band played a concert in the park.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The passage gives no examples or details."],"correct":2,"studyAid":{"definition":"Persuasive writing uses reasons and specific examples to convince the reader to agree with a certain point of view or take an action.","example":"Persuasive: 'You should recycle because it saves energy.' Not persuasive: 'The sun is hot today.'","strategyClue":"Look for the sentence that provides evidence of a positive result, as authors often use 'proof' to make their argument more convincing to the reader.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This detail demonstrates the tangible, positive impact of the action, which supports the author's claim that such efforts solve real problems.","incorrect":[{"choice":"The passage avoids the topic after the first sentence.","category":"Incorrect content observation","reason":"This is incorrect because the passage continues to discuss the cleanup, signs, and the reasons why the effort is important for the community."},{"choice":"The town band played a concert in the park.","category":"Irrelevant information","reason":"This information is not found in the passage provided and does not help persuade the reader about beach cleanup efforts."},"",{"choice":"The passage gives no examples or details.","category":"Factual inaccuracy","reason":"The passage actually provides specific examples, such as 'plastic wrappers' and 'bottle caps,' to prove that the beach cleanup was successful."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":170,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0171","version":3,"contentHash":"sha256:c501b8e61fc4b5a8cb93563eb55f7ec841c21513f5bdb5065663daf8293f237a","question":"Read the passage. Grade 5 challenge passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. Because the passage connects actions with results, readers can see why bike riders can prevent injuries by following safety rules. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich audience would most likely find this passage useful?","choices":["readers trying to learn a new song","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers who want to learn about the topic"],"correct":3,"studyAid":{"definition":"To identify the intended audience, look for the passage's main idea and purpose: is it to inform, entertain, or persuade?","example":"A book about planets is for people interested in science; a mystery novel is for people who enjoy suspenseful stories.","strategyClue":"Identify the main topic of the passage first, then eliminate any options that describe a different subject matter or a completely different type of writing.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information about bike safety and community efforts, which is useful for someone seeking knowledge or practical advice on that specific subject.","incorrect":[{"choice":"readers trying to learn a new song","category":"irrelevant topic content","reason":"The passage discusses bike safety and traffic rules, which has nothing to do with music, lyrics, or learning how to sing or play a song."},{"choice":"readers looking for a fantasy story with magic","category":"wrong genre classification","reason":"This passage is informational and non-fiction; it does not contain fictional characters, magic, or narrative plot elements associated with fantasy stories."},{"choice":"readers studying a recipe for dessert","category":"mismatched instructional text","reason":"A recipe provides steps for cooking food, while this passage provides instructions on safety. The goals and information types do not overlap."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":171,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0172","version":3,"contentHash":"sha256:db066d788a749937ec636bf32bd903a2a4ebf302d143bd51abdbfef59d8b5a2b","question":"Read the passage. Grade 5 challenge passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. Because the passage connects actions with results, readers can see why new bus routes made important places easier to reach. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to explain how new bus routes helped a neighborhood","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":0,"studyAid":{"definition":"An author's purpose is the reason they wrote a text, usually to explain something, persuade the reader, or tell a story.","example":"An encyclopedia entry (to explain), a speech about saving the environment (to persuade), a fable about a fox and a crow (to entertain).","strategyClue":"Look at the passage as a whole. Ask yourself, 'Is the author telling me a story, trying to convince me of something, or showing me how something works?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how new bus routes helped a neighborhood. The passage details specific changes (adding routes) and clear outcomes (shorter wait times, easier access to places), which shows an explanatory purpose.","incorrect":["",{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong text type","reason":"This passage describes real-life transportation improvements rather than a fictional story with characters and a plot twist."},{"choice":"to list unrelated facts without a main point","category":"missing main idea","reason":"The facts provided are not unrelated; they all focus on how public transit changes affected the community, centering on one clear theme."},{"choice":"to confuse readers about the topic","category":"illogical purpose","reason":"Authors write to inform, persuade, or entertain. Providing clear details about bus routes is meant to help readers understand the topic, not to make them confused."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":172,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0173","version":3,"contentHash":"sha256:8c8a8405b9198e4452e694794803501fdbfbac74df98ea0ebbd6b3dd5bf00313","question":"Read the passage. Grade 5 challenge passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. Because the passage connects actions with results, readers can see why many students worked together to prepare the school play. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich clue best shows that the author wants to describe?","choices":["A math poster showed different kinds of triangles.","Actors practiced lines while stage crew members painted scenery and tested lights.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":1,"studyAid":{"definition":"Descriptive writing uses specific details, actions, and examples to help the reader create a mental picture of a scene.","example":"Instead of saying 'the room was messy,' a writer might say 'piles of crumpled paper covered the desk and toys were scattered across the rug.'","strategyClue":"Look for the sentence that lists specific tasks or visual elements related to the main topic of the passage. Ignore sentences that provide information unrelated to the central theme.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence provides specific, vivid details about what each group of people was doing, which helps the reader visualize the activity of preparing for a play.","incorrect":[{"choice":"A math poster showed different kinds of triangles.","category":"irrelevant information","reason":"This sentence describes a completely different topic. The passage is about a school play, not a math lesson."},"",{"choice":"The passage avoids the topic after the first sentence.","category":"incorrect text analysis","reason":"This is false; the passage continues to add more specific details about the stage crew and the curtain rope after the first sentence."},{"choice":"The passage gives no examples or details.","category":"ignoring textual evidence","reason":"The author provides many examples, such as actors practicing, crew members painting, and a tangled rope being fixed."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":173,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0174","version":3,"contentHash":"sha256:d47bd57befa02fa6cc6a0f6255b0fcdd8317ae7427f2d9ec4bcfe57ba578cdf5","question":"Read the passage. Grade 5 challenge passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. Because the passage connects actions with results, readers can see why composting changed cafeteria scraps into useful soil material. The author presents the steps and results so readers understand how the process works.\n\nWhich audience would most likely find this passage useful?","choices":["readers studying a recipe for dessert","readers looking for a fantasy story with magic","readers who want to learn about the topic","readers trying to learn a new song"],"correct":2,"studyAid":{"definition":"To determine the target audience of a text, look at the main idea and the author's purpose. Informational texts are intended for readers who want to learn about facts, processes, or how things work.","example":"A cookbook is for people wanting to cook; a textbook is for people wanting to study science; a fantasy novel is for people wanting to be entertained.","strategyClue":"Identify the main purpose of the text—is it to entertain, persuade, or inform? Once you know the purpose, think about what kind of person would want that information.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information about the process of composting, which is a real-world scientific topic. This text is designed to inform and explain how a process works rather than to entertain or instruct on other subjects.","incorrect":[{"choice":"readers studying a recipe for dessert","category":"mismatched instructional content","reason":"While the passage mentions 'fruit peels', it does not list ingredients or provide steps for making food. It focuses on recycling waste, not cooking a recipe."},{"choice":"readers looking for a fantasy story with magic","category":"mismatched genre","reason":"The passage describes a realistic scientific process involving compost and soil. It contains no elements of fantasy, magic, or narrative adventure."},"",{"choice":"readers trying to learn a new song","category":"mismatched media type","reason":"The text explains a technical process through informational paragraphs. It lacks the structure of lyrics, rhythm, or musical notation needed for learning a song."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":174,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0175","version":3,"contentHash":"sha256:f8bf44753f4c69c2ed0ca622bb98dc79effdb697140ba5ccdf782f0a965154fc","question":"Read the passage. Grade 5 challenge passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. Because the passage connects actions with results, readers can see why students collected weather data to notice local patterns. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to confuse readers about the topic","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to explain how students studied weather"],"correct":3,"studyAid":{"definition":"The author's purpose is the reason why an author writes a text, such as to explain, inform, persuade, or entertain.","example":"An encyclopedia entry informs, a fairy tale entertains, and a science experiment guide explains.","strategyClue":"Look at the big picture: ask yourself if the passage is trying to teach you how something happens, or if it is just listing random things. Identify the main subject and check if the details support that single topic.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students studied weather. The passage focuses on the specific steps the students took to record data and why they collected that information, which directly informs the reader about their scientific process.","incorrect":[{"choice":"to confuse readers about the topic","category":"incorrect intent","reason":"The text uses clear, organized language to describe science observations. An author's purpose is rarely to confuse, and this passage succeeds in being informative."},{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect genre/purpose","reason":"The passage describes factual student activities rather than a fictional story. There is no plot, conflict, or twist, which are common elements of adventure stories."},{"choice":"to list unrelated facts without a main point","category":"disorganized structure","reason":"The facts provided are all related to weather tracking. The passage connects these details together to show the logical reason for the students' work."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":175,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0176","version":3,"contentHash":"sha256:73c3e6e4f04cc29298aede57acd177ad0122c530e5f3fa6351724d14e0c63f25","question":"Read the passage. Grade 5 challenge passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. Because the passage connects actions with results, readers can see why the recycling team helped the school waste less paper. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["They placed blue bins in classrooms and reminded students to use both sides of paper.","The nurse checked the first-aid supplies after lunch.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":0,"studyAid":{"definition":"Persuasive writing uses reasons, examples, and evidence to convince the reader to agree with an opinion or take action.","example":"Persuasive: 'We should walk to school because it is healthy and good for the planet.' Non-persuasive: 'We walk to school every morning at 8:00.'","strategyClue":"Look for sentences that describe actions or solutions that suggest a 'better way' to do things. Ask yourself: 'Does this sentence show that something is helpful or effective?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They placed blue bins in classrooms and reminded students to use both sides of paper. This sentence shows concrete, positive actions taken to solve a problem, which is a classic technique authors use to convince readers that a specific behavior is beneficial and worthy of support.","incorrect":["",{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence is unrelated to the topic of recycling and does not appear in the passage provided. Always verify that your evidence comes directly from the text."},{"choice":"The passage avoids the topic after the first sentence.","category":"incorrect text analysis","reason":"The passage actually builds upon the topic by providing specific details about classroom bins and paper usage, showing how the school successfully reduced waste."},{"choice":"The passage gives no examples or details.","category":"factual inaccuracy","reason":"The passage does include specific examples, such as 'blue bins' and 'using both sides of paper,' which help support the author's argument that recycling is an effective action."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":176,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0177","version":3,"contentHash":"sha256:c768751db6368e8261ed64d0c87b002915e7ef9997151616593d74fe9b6efe9d","question":"Read the passage. Grade 5 challenge passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. Because the passage connects actions with results, readers can see why the exhibit used artifacts and voices to teach local history. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["readers looking for a fantasy story with magic","readers who want to learn about the topic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":1,"studyAid":{"definition":"To determine the target audience, identify the passage's main purpose (to inform, to entertain, or to persuade) and match it with the needs of specific types of readers.","example":"A factual article about space helps science students; a suspenseful story about a haunted house helps readers who enjoy thrillers.","strategyClue":"Look at the key nouns and verbs in the text to identify the subject matter; then, ask yourself, 'What kind of person would look for this type of information?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage describes a museum exhibit about local history using artifacts, tools, and oral histories, which directly informs and educates the reader about real-world facts.","incorrect":[{"choice":"readers looking for a fantasy story with magic","category":"wrong genre/theme","reason":"The passage focuses on historical artifacts like tools and letters. It does not contain magical elements, supernatural events, or fictional settings."},"",{"choice":"readers studying a recipe for dessert","category":"mismatched instructional goal","reason":"A recipe would need specific ingredients and step-by-step instructions. This passage describes an educational museum exhibit, not a cooking process."},{"choice":"readers trying to learn a new song","category":"wrong media format","reason":"The passage mentions recordings of voices, but it discusses historical memories and artifacts rather than musical notes, rhythms, or lyrics needed to learn a song."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":177,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0178","version":3,"contentHash":"sha256:24929980f5f2e9a1a2b480a2369c08cf90dfee7b5adf5570d1aac8e85cfd87db","question":"Read the passage. Grade 5 challenge passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. Because the passage connects actions with results, readers can see why testing and revising helped the robotics club improve its robot. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to list unrelated facts without a main point","to tell a made-up adventure with a surprising ending","to explain how testing improved a robot","to confuse readers about the topic"],"correct":2,"studyAid":{"definition":"The author's purpose is the reason a text was written: to inform, to persuade, to entertain, or to explain a process.","example":"An encyclopedia entry informs, a cookbook explains a process, and a mystery novel entertains.","strategyClue":"Look at the first and last sentences of the passage to identify the 'big picture' topic. Ask yourself: 'Does this passage want me to learn something, feel something, or change my mind?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how testing improved a robot. The passage describes a clear cause-and-effect relationship between the testing process and the final improvement of the robot, which matches the author's clear focus on the 'how' and 'why' of the work.","incorrect":[{"choice":"to list unrelated facts without a main point","category":"lack of coherence","reason":"The sentences are not random; they all connect to the theme of robot testing, so this choice ignores the clear logical structure of the text."},{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong text type","reason":"The passage is expository, not narrative. It describes a factual process rather than telling a story with fictional characters or a plot twist."},"",{"choice":"to confuse readers about the topic","category":"incorrect author motive","reason":"The author uses descriptive steps and logical transitions to make the process clearer, not to make it harder to understand."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":178,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0179","version":3,"contentHash":"sha256:37fdcef70f92bdb6326be497b91e46b87ecfd669ae24fd954afb8afd382fc256","question":"Read the passage. Grade 5 challenge passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. Because the passage connects actions with results, readers can see why the breakfast cart helped more students start the day with food. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The passage gives no examples or details.","The science lab received new magnifying glasses.","The passage avoids the topic after the first sentence.","The cart offered fruit, yogurt, and whole-grain muffins near the front door."],"correct":3,"studyAid":{"definition":"Persuasive writing uses reasons, evidence, and logical points to convince a reader to agree with an opinion or support a specific action.","example":"Fact: 'Our school is recycling.' Persuasive argument: 'Our school should recycle because it keeps the campus clean and helps protect the planet.'","strategyClue":"Look for sentences that explain why an action is good or why a problem was solved. Persuasive authors often use these 'why' statements to encourage the reader to feel a certain way.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The cart offered fruit, yogurt, and whole-grain muffins near the front door. This sentence provides factual evidence of the program's success and helpful nature, which helps convince the reader that the breakfast cart is a positive initiative worth supporting.","incorrect":[{"choice":"The passage gives no examples or details.","category":"factual error","reason":"This is incorrect because the passage provides specific details, such as the types of food offered and where the cart is located, to support its point."},{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"This statement is not found in the text provided. When identifying a persuasive clue, you must only use evidence actually present in the author's writing."},{"choice":"The passage avoids the topic after the first sentence.","category":"misreading the text","reason":"This is incorrect because the author continues to discuss the breakfast cart throughout the entire passage, explaining why it helps students and why people should support it."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":179,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0180","version":3,"contentHash":"sha256:25d6f30c9952cde0524fd82628871d47b1469d587d8edcd893809db56cbb67a2","question":"Read the passage. Grade 5 challenge passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. Because the passage connects actions with results, readers can see why trail signs helped visitors move safely and learn about nature. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["people who care about outdoor spaces","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":0,"studyAid":{"definition":"To identify the intended audience, look for the main topic of the text and ask who would benefit most from the information provided.","example":"A book about car engines is for mechanics; a book about space travel is for science enthusiasts.","strategyClue":"List three main keywords from the passage (e.g., trail, nature, signs) and ask yourself who would actually spend time reading about those specific things.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: people who care about outdoor spaces. The passage provides descriptive details about trail markings, benches, and nature education, which are directly relevant to hikers, nature lovers, or people interested in park maintenance.","incorrect":["",{"choice":"readers looking for a fantasy story with magic","category":"mismatched literary genre","reason":"This passage is factual and descriptive about park trails; it does not contain the imaginary creatures, magic, or plot twists found in a fantasy story."},{"choice":"readers studying a recipe for dessert","category":"incompatible content topic","reason":"The text focuses on outdoor park improvements and nature, not on ingredients, measurements, or cooking instructions required for a recipe."},{"choice":"readers trying to learn a new song","category":"irrelevant instructional purpose","reason":"The passage explains trail features to help visitors, but it contains no lyrics, musical notes, or rhythms needed to learn a song."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":180,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0181","version":3,"contentHash":"sha256:cd2580d52e9a6e32dcff1db8505e1454be02525bf0168d5e436a70dfb26a284f","question":"Which sentence uses the infinitive phrase for emphasis?","choices":["I like to eat ice cream with chocolate sauce.","We were tardy to class.","To read for pleasure is a goal of serious students.","We took a break to buy a snack from the vending machine."],"correct":2,"explanation":{"correct":"Answer: To read for pleasure is a goal of serious students. An infinitive phrase acts as the subject of this sentence, placing the action at the very beginning to emphasize the importance of that specific goal.","incorrect":[{"choice":"I like to eat ice cream with chocolate sauce.","category":"standard object placement","reason":"In this sentence, 'to eat ice cream' follows the verb 'like' as a direct object rather than being moved to the front for emphasis."},{"choice":"We were tardy to class.","category":"prepositional phrase","reason":"The word 'to' here is followed by a noun ('class'), which makes it a prepositional phrase, not an infinitive verb phrase."},"",{"choice":"We took a break to buy a snack from the vending machine.","category":"adverbial purpose phrase","reason":"While 'to buy' is an infinitive, it is placed at the end to explain *why* they took a break, rather than being moved to the start of the sentence for emphasis."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sequence":181,"sourceFile":"Advanced-1_Writing strategies_Application_Style.pdf","sourceQuestionNumber":2,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]},"studyAid":{"definition":"An infinitive is a verb form starting with 'to' (to jump, to see, to learn). Placing an infinitive phrase at the beginning of a sentence makes it the subject and gives it extra focus.","example":"To win the game was her only hope. (Emphasis) vs. Her only hope was to win the game. (Standard)","strategyClue":"Look for the sentence where the 'to + verb' phrase is moved to the very front of the sentence to act as the subject, rather than sitting in the middle or end.","link":"","linkText":""}},{"id":"reading-comprehension-authors-purpose-q0182","version":3,"contentHash":"sha256:b0813210b17bd51bcbd17791739b1104544f7b331df73de5d68459dd529542f7","question":"Identify the sentence that contains a dependent clause.","choices":["The students will take an exam after lunch.","We ate the sandwiches, but we forgot about the potato salad.","When the movie ended, Sally took me home.","Finish your homework in the morning."],"correct":2,"explanation":{"correct":"Answer: When the movie ended, Sally took me home. This sentence contains a dependent clause ('When the movie ended') because it begins with a subordinating conjunction and cannot stand alone as a complete sentence.","incorrect":[{"choice":"The students will take an exam after lunch.","category":"simple sentence structure","reason":"This sentence is a simple sentence. 'After lunch' is a prepositional phrase, not a dependent clause, because it does not contain both a subject and a verb."},{"choice":"We ate the sandwiches, but we forgot about the potato salad.","category":"compound sentence structure","reason":"This is a compound sentence joined by the coordinating conjunction 'but'. Both parts are independent clauses that can stand alone as complete sentences."},"",{"choice":"Finish your homework in the morning.","category":"imperative sentence type","reason":"This is an imperative sentence (a command). It has an implied subject ('you'), but it does not contain a dependent clause."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sequence":182,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":10,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]},"studyAid":{"definition":"A dependent clause is a group of words that has a subject and a verb but does not express a complete thought, usually starting with words like because, although, if, or when.","example":"Independent: I went home. Dependent: Because I was tired, I went home.","strategyClue":"Look for a group of words that contains a subject and a verb but feels 'unfinished' or like it needs more information to make sense on its own.","link":"","linkText":""}},{"id":"reading-comprehension-authors-purpose-q0183","version":3,"contentHash":"sha256:df998bd14f89a97460fc94bfea79dbd75c5d6bc4046107d9b406ae1e00b2edd4","question":"Which sentence demonstrates correct subject – verb agreement?","choices":["Students in that English class write many essays.","The crowd from the game are walking outof the stadium.","A student with six classes are going to be easy.","Her class with twenty students are supposed to ride in that little van."],"correct":0,"explanation":{"correct":"Answer: Students in that English class write many essays. The subject is 'Students' (plural), so the verb must be 'write' (plural form). The phrase 'in that English class' is just extra information and does not change the subject.","incorrect":["",{"choice":"The crowd from the game are walking outof the stadium.","category":"subject-verb disagreement","reason":"The subject is 'crowd', which is a singular collective noun. It requires the singular verb 'is', not the plural 'are'."},{"choice":"A student with six classes are going to be easy.","category":"subject-verb disagreement","reason":"The subject is 'A student', which is singular. Therefore, it needs the singular verb 'is', not the plural 'are'."},{"choice":"Her class with twenty students are supposed to ride in that little van.","category":"subject-verb disagreement","reason":"The subject is 'class', which is singular. Even though 'students' is near the verb, the true subject is 'class', so the verb must be the singular 'is'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sequence":183,"sourceFile":"Advanced-2_Writing strategies_Application_Style.pdf","sourceQuestionNumber":1,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]},"studyAid":{"definition":"The subject and verb must agree in number: singular subjects take singular verbs, and plural subjects take plural verbs. Ignore extra words that come between the subject and the verb.","example":"The dog runs. / The dogs run. / The box of chocolates is sweet.","strategyClue":"Put your hand over any descriptive phrases starting with 'of', 'with', or 'in' to see the simple subject clearly. Then, check if that hidden subject matches the action word.","link":"","linkText":""}},{"id":"reading-comprehension-authors-purpose-q0184","version":3,"contentHash":"sha256:e09af76b7d050491e4f84e3aca22fc0b12ee0eee5eb98529f238448d1896b33a","question":"Read the following passage and identify the appropriate audience. Several large roads were built in the 1970’s because people were moving from the cities to the suburbs. The roads cost a lot to build but have become major routes of transportation in the United States.","choices":["people who like computers","people who like math","people who like houses","people who like maps"],"correct":3,"explanation":{"correct":"Answer: people who like maps. The passage focuses on transportation networks, urban development, and routes between cities and suburbs, which are all key subjects found on maps.","incorrect":[{"choice":"people who like computers","category":"irrelevant subject matter","reason":"The passage discusses roads and city planning, not computer hardware or software."},{"choice":"people who like math","category":"unrelated topic focus","reason":"While the passage mentions the 1970s, it focuses on transportation infrastructure rather than mathematical theories or calculations."},{"choice":"people who like houses","category":"misinterpreted focus","reason":"Although the passage mentions moving to suburbs, it focuses on the roads used to travel there, not the design or architecture of the houses themselves."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["reading comprehension","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sequence":184,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":12,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]},"studyAid":{"definition":"The intended audience is the group of people most likely to be interested in the information presented in the text.","example":"A text about how to bake a cake is for cooks; a text about how to build a computer is for technology fans.","strategyClue":"Look at the main topic of the passage—in this case, transportation routes—and ask yourself which type of hobbyist or reader would care most about that specific topic.","link":"","linkText":""}},{"id":"reading-comprehension-authors-purpose-q0185","version":3,"contentHash":"sha256:b0526e5dfa4f42ce9580d65ab2c80d3b258104b44562d5b37f72290f0ad2b48b","question":"Read the following passage and identify the appropriate audience. The 4 grade is having a book exchange on Friday, October 14, in Room 16 at the Liberty School. Come, browse and bring a book to exchange.","choices":["teachers","ministers","nurses","students"],"correct":3,"explanation":{"correct":"Answer: students. The passage describes a school event—a book exchange—which is a classic activity designed for children attending classes at a school.","incorrect":[{"choice":"teachers","category":"mismatched target audience","reason":"While teachers might help organize the event, a 'book exchange' in a classroom for a specific grade level is primarily meant for the students themselves to participate in."},{"choice":"ministers","category":"irrelevant professional group","reason":"Ministers work in religious settings. There is no information in the text that suggests this event is related to a place of worship or a religious group."},{"choice":"nurses","category":"irrelevant professional group","reason":"Nurses work in medical environments. Since the event is a book exchange held in a classroom at a school, this group is not the intended audience."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["reading comprehension","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sequence":185,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":12,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]},"studyAid":{"definition":"The audience is the group of people for whom a message is intended. You can identify them by looking for clues about the location, the topic, and the activity being described.","example":"A 'menu' is for customers at a restaurant; a 'symptom checklist' is for patients at a clinic; a 'homework schedule' is for students in a class.","strategyClue":"Look at the setting (Room 16) and the activity (book exchange). Ask yourself: 'Which group of people usually spends their day in a school room doing this type of activity?'","link":"","linkText":""}},{"id":"reading-comprehension-authors-purpose-q0186","version":3,"contentHash":"sha256:b0bdf4bd1903ee34c584710aa79c9463ac3f6ab472fe9da9635a9238b9a5a6cc","question":"Read the riddle. What is black and white and read allover? A newspaper What is the purpose of this riddle?","choices":["to educate","to persuade","to amuse","to inform"],"correct":2,"explanation":{"correct":"Answer: to amuse. A riddle is a type of wordplay designed to be funny or clever; its primary purpose is to entertain the listener.","incorrect":[{"choice":"to educate","category":"incorrect purpose","reason":"This riddle does not teach a lesson or explain a complex subject, so it is not meant to educate the reader."},{"choice":"to persuade","category":"incorrect purpose","reason":"To persuade means to convince someone to change their mind or take action. This riddle is just for fun, not for convincing."},"",{"choice":"to inform","category":"incorrect purpose","reason":"An informational text gives facts or news. Since this is a joke about a newspaper, its goal is humor, not providing factual information."}]},"studyAid":{"definition":"The author's purpose is the reason why a piece of writing was created. The three most common purposes are to inform, to persuade, and to entertain (amuse).","example":"To inform: A science textbook. To persuade: A food advertisement. To amuse: A joke book or a funny riddle.","strategyClue":"Ask yourself if the writing is meant to teach you a fact, change what you think, or just make you smile or laugh.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":16,"sourceCategory":"reading-test","sourceGrade":3,"sequence":186,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0187","version":3,"contentHash":"sha256:3aad9d788e985802295c132efb8dc055ec8d8c35bdd1ba9565ee6468cbc55c16","question":"Read the advertisement. If Jerry is looking for a bed for his St. Bernard do g, what price can he expect to p ay?","choices":["$31.99","$25.99","$39.99","$ 56.99"],"correct":3,"explanation":{"correct":"Answer: $56.99. When looking for a bed for a St. Bernard, you must identify the bed size meant for large dogs. The advertisement lists the price for the Large Bed at $56.99.","incorrect":[{"choice":"$31.99","category":"wrong size classification","reason":"This price corresponds to the Small Bed. A St. Bernard is a giant breed, so it would not fit comfortably on a small bed."},{"choice":"$25.99","category":"misreading data table","reason":"This price does not match the large or extra-large options. Check the advertisement list carefully to match the dog's size with the correct price row."},{"choice":"$39.99","category":"incorrect price mapping","reason":"This price corresponds to the Medium Bed. A St. Bernard is too large for a medium-sized bed."},""]},"studyAid":{"definition":"Reading comprehension requires matching specific details from a text, such as a price or size, to the correct category.","example":"Small bed: $31.99, Medium bed: $39.99, Large bed: $56.99","strategyClue":"First, identify the size category that matches a very large dog breed. Then, scan the list to find the price directly next to that specific category.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Advanced-3_Informational Text.pdf","sourceQuestionNumber":6,"sourceCategory":"informational-text","sourceGrade":3,"sequence":187,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0188","version":3,"contentHash":"sha256:2258df779c772513455fc4aa89c8bcd11c2d80b0fe459c5b4c9b777369189648","question":"Read the story and answer the question. Who yelled?","choices":["D ad","Rachel","the teacher","John"],"correct":1,"explanation":{"correct":"Answer: Rachel. According to the text, Rachel is the character identified as the one who yelled when the event occurred.","incorrect":[{"choice":"D ad","category":"incorrect character","reason":"While the dad might appear in the story, he is not the one who performed the action of yelling in this specific passage."},"",{"choice":"the teacher","category":"incorrect character","reason":"The text does not name the teacher as the person yelling; check the paragraph to see which name is linked to that specific action."},{"choice":"John","category":"incorrect character","reason":"John is a character in the story, but he is not the one who yelled. Always double-check the specific sentence describing the action."}]},"studyAid":{"definition":"Reading comprehension requires finding specific details by matching an action in the question to the character who performed it in the story.","example":"Question: Who sat? Text: Sam sat down. Answer: Sam.","strategyClue":"Scan the paragraph for the keyword 'yelled' and look immediately before that word to see which name is attached to it.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Basic-2_Informational Text.pdf","sourceQuestionNumber":8,"sourceCategory":"informational-text","sourceGrade":3,"sequence":188,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0189","version":3,"contentHash":"sha256:bc9072df67fdaa52fdfd322c487f3df62ec71afc3df42353dfe65fc2821d9628","question":"Read the advertisement, then complete the sentence below. If you eat Campbell’s Soup for lunch you will ___ __________.","choices":["b e hungry 1 hour later","eat too much","have fun","get sick to your stomach"],"correct":2,"explanation":{"correct":"Answer: have fun. In the context of the advertisement, this choice captures the positive, encouraging tone often used in marketing to promote a product's benefits to the consumer.","incorrect":[{"choice":"b e hungry 1 hour later","category":"advertisement purpose","reason":"Advertisements are written to make products sound appealing. Suggesting that the soup will leave you hungry quickly would discourage people from buying it."},{"choice":"eat too much","category":"negative product outcome","reason":"Companies avoid suggesting that their food products lead to negative physical feelings like overeating, as it makes the product seem unhealthy."},"",{"choice":"get sick to your stomach","category":"inappropriate marketing tone","reason":"This is a negative outcome that would drive customers away. Advertisements focus on positive experiences to help sell the item."}]},"studyAid":{"definition":"Advertisements use persuasive language to highlight the positive benefits or joy that a product will bring to the user.","example":"Healthy choice: 'Feel energized all afternoon.' Incorrect choice: 'Feel tired and slow.'","strategyClue":"Look at the tone of the sentence. Since an advertisement aims to sell a product, choose the option that describes a positive result rather than a negative one.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Basic-4_Informational Text.pdf","sourceQuestionNumber":3,"sourceCategory":"informational-text","sourceGrade":3,"sequence":189,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0190","version":3,"contentHash":"sha256:7e55cd7317186f853eb1194b072f1d7ea06caa4d71fbb38fb003cc671f074109","question":"Look at the ad. This ad makes you want to buy the garbage bags because:","choices":["They are cheap.","They are black.","They are thick.","They are made of plastic."],"correct":2,"explanation":{"correct":"Answer: They are thick. Advertisements often highlight a product's strength or quality to convince the buyer of its value. Being 'thick' implies durability and resistance to tearing, which is a desirable trait for a garbage bag.","incorrect":[{"choice":"They are cheap.","category":"Inference vs. Advertising","reason":"While companies sometimes mention price, the prompt asks why you would want to buy them specifically; a bag that is just cheap might break easily. Thickness suggests quality over mere price."},{"choice":"They are black.","category":"Irrelevant detail","reason":"The color of a garbage bag does not impact how well it performs its job. An ad focuses on the benefits that solve a problem, not the visual style."},"",{"choice":"They are made of plastic.","category":"Basic attribute","reason":"This is a factual description of almost all garbage bags. It does not provide a reason for a shopper to choose one brand over another, unlike the strength implied by thickness."}]},"studyAid":{"definition":"When identifying the purpose of an advertisement, look for the specific benefit that explains why the product is better than others. Good ads persuade you by promising a solution to a problem.","example":"A car ad says it is 'fuel-efficient' to save money, not just that it has four tires. A soap ad says it 'kills 99% of germs' to show why it is better than plain water.","strategyClue":"Ask yourself, 'Which of these features makes the bag most useful for its main job of holding heavy trash without breaking?'","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-10_Informational Text.pdf","sourceQuestionNumber":4,"sourceCategory":"informational-text","sourceGrade":3,"sequence":190,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0191","version":3,"contentHash":"sha256:0e0e8d0bd2b2dcf425e96b3af4ea2be9dbb16d930b74040c28b1448309e160cd","question":"Look at the. ad How does this ad catch your attention?","choices":["of fers great craft ideas","appeal to save money","free computer time","gardening ideas"],"correct":1,"explanation":{"correct":"Answer: appeal to save money. The question asks how the ad catches attention. Looking at the context of an advertisement, an appeal to save money is a common persuasive technique used to interest a viewer.","incorrect":[{"choice":"of fers great craft ideas","category":"misreading the text","reason":"This phrase contains a typo and does not directly answer the specific question about how the ad catches the viewer's attention."},"",{"choice":"free computer time","category":"irrelevant information","reason":"Unless the ad is specifically about a computer lab, this detail is likely not the primary way the ad is designed to hook an audience."},{"choice":"gardening ideas","category":"unsupported by context","reason":"This choice describes a topic rather than a persuasive method or an attention-grabbing strategy used in an advertisement."}]},"studyAid":{"definition":"When analyzing an advertisement, look for the 'hook'—the specific strategy, offer, or image the creator uses to make you want to pay attention.","example":"A 'buy one get one free' sale hooks you with value; a bright picture of a puppy hooks you with emotion.","strategyClue":"Ask yourself, 'Why would someone stop scrolling or reading to look at this?' Identify the persuasive element that creates interest rather than just naming a topic.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-12_Informational Text.pdf","sourceQuestionNumber":4,"sourceCategory":"informational-text","sourceGrade":3,"sequence":191,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0192","version":3,"contentHash":"sha256:29f6753383def5939099251b1b9fd5e315e13a0deb2d137b4219bc8fc766bbd6","question":"Read the following advertisement. Worldwide Headquarters: 1932 Wynnton Road, Columbus, Georgia 31999 -0001. What is a benefit of AFLAC insurance?","choices":["AFLAC p ays cash directly to you to help with loss of income.","It is the most expensive insurance planyou can buy.","An AFLAC associate will answer your questions on Thursday.","This plan is comprehensive and you do not need another insurance plan."],"correct":0,"explanation":{"correct":"Answer: AFLAC pays cash directly to you to help with loss of income. This choice correctly identifies a primary benefit of the service, which is financial support during income loss.","incorrect":["",{"choice":"It is the most expensive insurance planyou can buy.","category":"incorrect claim","reason":"Insurance advertisements focus on value and protection, not high costs. Promoting high prices as a benefit does not align with the purpose of an insurance policy."},{"choice":"An AFLAC associate will answer your questions on Thursday.","category":"irrelevant information","reason":"While this might be a helpful detail about a meeting, it is a logistical fact rather than a benefit of the insurance plan itself."},{"choice":"This plan is comprehensive and you do not need another insurance plan.","category":"unsupported claim","reason":"The text does not state that this plan replaces all other insurance needs; assuming you need no other insurance is a logical leap not supported by the advertisement."}]},"studyAid":{"definition":"A benefit is a helpful or positive feature of a product or service that makes life easier for the customer.","example":"Benefit: This blender saves time by cleaning itself. Non-benefit: This blender is blue.","strategyClue":"Scan the text for keywords like 'pays', 'covers', or 'helps'. Ask yourself, 'Which of these choices directly describes how the product helps the customer in their daily life?'","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-12_Informational Text.pdf","sourceQuestionNumber":10,"sourceCategory":"informational-text","sourceGrade":3,"sequence":192,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0193","version":3,"contentHash":"sha256:81684e58f2cf4d86003f4c0f16d778e38e5cff2d30904b8593a771e288348ae7","question":"Read the classified advertisement. Choose the correct statement.","choices":["The golden retriever was lost in Idaho Falls.","The dog was found wearing a purple collar.","The black lab found in Shelley is a female dog.","The black lab is around six months old."],"correct":3,"explanation":{"correct":"Answer: The black lab is around six months old. This statement directly reflects the information provided in the classified advertisement, which specifies the breed, age, and approximate location.","incorrect":[{"choice":"The golden retriever was lost in Idaho Falls.","category":"Incorrect breed information","reason":"The text describes a black lab, not a golden retriever. Always double-check the breed mentioned in the source text before confirming a detail."},{"choice":"The dog was found wearing a purple collar.","category":"Incorrect physical detail","reason":"While a collar color might be mentioned in similar ads, check the provided text carefully. If the text specifies a different color or no collar, this statement is factually unsupported."},{"choice":"The black lab found in Shelley is a female dog.","category":"Incorrect gender detail","reason":"Verify the gender of the pet described in the ad. If the ad refers to the dog as 'he' or 'him,' identifying it as female is an inaccurate detail."},""]},"studyAid":{"definition":"Reading comprehension means finding and understanding facts directly stated in a text without changing the meaning.","example":"Text: 'Sam has a red bike.' Statement: 'Sam has a blue bike.' (Incorrect). Statement: 'Sam has a red bike.' (Correct).","strategyClue":"Highlight the specific keywords in the question (like age, color, or location) and scan the text for those exact words to see if the sentence matches.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-13_Informational Text.pdf","sourceQuestionNumber":4,"sourceCategory":"informational-text","sourceGrade":3,"sequence":193,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0194","version":3,"contentHash":"sha256:d2fdbe69fafa9679d63b19bfd5fd98d4ebfa6ac8d8c0e18d0886e8e0f1b2beb1","question":"Read the advertisement. NIE Program Ad vertisement. Jeanet te Edmister 542 -6777. Where should donated books be taken?","choices":["to the NIE office","to Jeanette Edmister","to 333 Southgate Mile","to the Post Register Circulation Department"],"correct":3,"explanation":{"correct":"Answer: to the Post Register Circulation Department. The advertisement specifically instructs readers to deliver their donated books to this location for the program.","incorrect":[{"choice":"to the NIE office","category":"misreading program details","reason":"While the ad mentions the NIE program, it does not instruct you to bring books to that office. Look for the specific 'drop off' location mentioned in the text."},{"choice":"to Jeanette Edmister","category":"confusing contact information","reason":"Jeanette Edmister is the person to call for more information, but the ad does not tell you to deliver physical books to her personally."},{"choice":"to 333 Southgate Mile","category":"misidentifying location details","reason":"This is likely a random address or office location not specified in the advertisement as the collection point for your donated books."},""]},"studyAid":{"definition":"Reading comprehension requires locating specific facts in a text by scanning for keywords related to the question asked.","example":"Question: 'What time does the store close?' Text: 'We are open until 9 PM.' Answer: 9 PM.","strategyClue":"Scan the advertisement for words related to 'donated books' or 'drop off' and look for the specific place name or address listed immediately after those key terms.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-13_Informational Text.pdf","sourceQuestionNumber":6,"sourceCategory":"informational-text","sourceGrade":3,"sequence":194,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0195","version":3,"contentHash":"sha256:24b41e97f4a853a4676e88e447495d461ec17b333ed58ddde03b44726ef6671a","question":"Read the passage. Abraham Lincoln wasn’t the sort of man who could lose himself in a crowd. After all, he stood six feet four inches tall, and to top it off, he wore a high silk hat. His height was mostly in his long, bony legs. When he sat in a chair, he seemed no taller than anyone else. It was only when he stood up that he towered above other men. At first glance most people thoughthe was homely. Lincolnthought so too, referring once to his, “poor, lean, lank face.” As a young man he was sensitive about his ga wky looks, but intime, he learned to laugh at himself. When a rival called h-im “two faced” during a political debate, Lincoln replied: “I leave it to m y audience. If I had another face, do you think I’d wear this one?” According to those who knew him, Lincol n was a man of many faces. In repose he often seemed sad and gloomy. But w hen he began to speak, hisexpression changed. “The Mysteriou s Mr. Lincoln, Elements of Literature, Introductory Cou rse. Holt, Rinehart and Winston, 1997. Select the appropriate genre for this passage.","choices":["non fiction","fiction","personal note","journal"],"correct":0,"explanation":{"correct":"Answer: non fiction. This passage is non-fiction because it describes real historical events and facts about Abraham Lincoln, who was a real person, rather than a made-up story.","incorrect":["",{"choice":"fiction","category":"genre identification","reason":"Fiction refers to stories that are invented or imagined. Because this passage describes a true historical figure and actual events, it cannot be fiction."},{"choice":"personal note","category":"text format","reason":"A personal note is typically a private message between individuals. This text is an informative excerpt meant for a general audience to learn about history."},{"choice":"journal","category":"genre identification","reason":"A journal is a private, daily record of personal thoughts. This passage is a biographical excerpt from a textbook, written in the third person about a historical subject."}]},"studyAid":{"definition":"Non-fiction is writing that is based on facts, real events, and real people, intended to inform or document history.","example":"Biographies, history textbooks, and science articles are all non-fiction. Novels and fairy tales are fiction.","strategyClue":"Ask yourself if the person or events in the passage are real or imagined. If the text provides facts about a person who truly lived, identify it by its factual category.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-13_Informational Text.pdf","sourceQuestionNumber":8,"sourceCategory":"informational-text","sourceGrade":3,"sequence":195,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0196","version":3,"contentHash":"sha256:63d95a75448570013d5e66644553dd69bf8e1120cd110666728fff21cfdd99ed","question":"Read the classified advertisement. Mary loves animals. She has had cats, dogs, horses, hamsters, and even a s nake! There is not a pet she doesn’t love. Barbara is allergic to fur and has only one pet: a turtle. Which statement do you know is true?","choices":["Barbara loves do gs.","Mary would like having a pet cat.","Barbara is allergic to snakes.","Mary is allowed to have any pet she wants."],"correct":1,"explanation":{"correct":"Answer: Mary would like having a pet cat. The text explicitly states that Mary 'loves animals' and 'has had cats,' which proves that she enjoys their company.","incorrect":[{"choice":"Barbara loves do gs.","reason":"\"Barbara loves do gs.\" gives a different purpose from the one shown by the passage."},"",{"choice":"Barbara is allergic to snakes.","category":"misreading the text","reason":"The text states Barbara is allergic to fur. Snakes do not have fur, so we cannot conclude she is allergic to them based on this information."},{"choice":"Mary is allowed to have any pet she wants.","category":"assumption error","reason":"While Mary loves many animals, the text never mentions the rules or permissions regarding what pets she is allowed to own."}]},"studyAid":{"definition":"A true statement must be supported by direct evidence in the text. An inference or assumption that isn't stated cannot be considered a proven fact.","example":"Text: 'Sam ran home because it was raining.' Fact: It was raining. Assumption: Sam dislikes being wet (not explicitly stated).","strategyClue":"Highlight every sentence in the text that mentions the specific subject of the choice. If you cannot point to a sentence that confirms the idea, the statement is not proven.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-14_Informational Text.pdf","sourceQuestionNumber":4,"sourceCategory":"informational-text","sourceGrade":3,"sequence":196,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0197","version":3,"contentHash":"sha256:4de33425df8f88d945a99e49eea297ff7673f9b88ab9bb9fd4363a6dbe8c40e4","question":"Read the passage. What is this ad trying to sell?","choices":["yummy d rinks","juicy punch","juicy candy","cool drinks"],"correct":1,"explanation":{"correct":"Answer: juicy punch. The ad specifically mentions 'juicy punch' as the product name. When answering reading comprehension questions, always look for the exact name or brand mentioned in the text.","incorrect":[{"choice":"yummy d rinks","category":"vague word choice","reason":"'Yummy drinks' is a general description, not the specific product name used in the advertisement."},"",{"choice":"juicy candy","category":"incorrect product type","reason":"The ad refers to a liquid, not a solid candy. Always double-check that your answer matches the type of item being described."},{"choice":"cool drinks","category":"generalization error","reason":"'Cool drinks' is too broad. The advertisement identifies a specific item, and you must pick the specific name provided."}]},"studyAid":{"definition":"Comprehension means finding the exact details the author gives you. A specific product name is a key detail that should never be replaced with a general description.","example":"If the ad says 'Zap Cola', do not choose 'soda' or 'bubbly drink'; choose 'Zap Cola'.","strategyClue":"Scan the text for proper nouns or words that sound like names and compare them word-for-word against the options provided.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-2_Informational Text.pdf","sourceQuestionNumber":2,"sourceCategory":"informational-text","sourceGrade":3,"sequence":197,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0198","version":3,"contentHash":"sha256:e4826ac7c34f6d6eeb91798ee813b00b3d15eda02647aa67dddecfe9229c4360","question":"Read the passage. What is the purpose of this advertisement?","choices":["to sell tomatoes","to read for fun","to sell Soupy Soup","to sell chicken"],"correct":2,"explanation":{"correct":"Answer: to sell Soupy Soup. Advertisements are created by companies specifically to persuade consumers to buy their product, which in this case is the specific brand mentioned, Soupy Soup.","incorrect":[{"choice":"to sell tomatoes","category":"too narrow focus","reason":"While tomatoes might be an ingredient, the purpose of the ad is to sell the whole product—Soupy Soup—rather than just one of its parts."},{"choice":"to read for fun","category":"wrong text purpose","reason":"Reading for fun is the purpose of stories or poems. Advertisements are functional texts written to persuade or inform potential buyers."},"",{"choice":"to sell chicken","category":"incorrect product focus","reason":"The advertisement is for Soupy Soup, not a specific ingredient like chicken. Always look for the main product name mentioned in the ad."}]},"studyAid":{"definition":"The purpose of an advertisement is to persuade people to buy a product or use a service.","example":"An ad for sneakers is to sell shoes; an ad for a car wash is to sell cleaning services.","strategyClue":"Ask yourself, 'What does the company want me to do after reading this?' Look for the specific name of the product being promoted in the text.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-3_Informational Text.pdf","sourceQuestionNumber":2,"sourceCategory":"informational-text","sourceGrade":3,"sequence":198,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0199","version":3,"contentHash":"sha256:9182b781941064214a16dca66c50f631a37c29c2487596e1c777b19cfd4028df","question":"Read the ad then answer the question. What canyou believe about this ad?","choices":["it is organically grown","it smells better than anything in the world","others will want hair as nice as yours","superhair is the best buy"],"correct":3,"explanation":{"correct":"Answer: superhair is the best buy. Ads often use opinionated, persuasive language like 'best' to convince you to purchase their specific product.","incorrect":[{"choice":"it is organically grown","category":"not supported by text","reason":"The ad does not mention the ingredients or the way the product was made, so we cannot conclude it is organically grown."},{"choice":"it smells better than anything in the world","category":"unverifiable absolute claim","reason":"This is an extreme claim that cannot be proven. Ads often exaggerate, and there is no evidence provided to support this comparison."},{"choice":"others will want hair as nice as yours","category":"speculative consumer reaction","reason":"While an ad might suggest this outcome, it is a prediction about how other people feel, not a fact we can verify about the product itself."},""]},"studyAid":{"definition":"Fact-based claims can be proven with evidence, while opinions are beliefs or feelings that cannot be proven true or false.","example":"Fact: 'This shampoo contains aloe.' Opinion: 'This is the greatest shampoo ever made.'","strategyClue":"Look for words that express personal opinion or superlative judgments like 'best', 'worst', or 'greatest' instead of specific details about the product's features.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-4_Informational Text.pdf","sourceQuestionNumber":2,"sourceCategory":"informational-text","sourceGrade":3,"sequence":199,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0200","version":3,"contentHash":"sha256:29191a74e6f1edce2898a4b6fdcbc9e316f466c047a4292467068759b028437c","question":"Read the sentence. Rachel painted her face. Inthis sentence, her is a _________?","choices":["verb","ad verb","noun","pronoun"],"correct":3,"explanation":{"correct":"Answer: pronoun. The word 'her' is a possessive pronoun because it takes the place of a noun to show ownership or relationship.","incorrect":[{"choice":"verb","category":"action word identification","reason":"A verb is an action word like 'painted'. 'Her' does not show an action, so it cannot be a verb."},{"choice":"ad verb","category":"adverb vs pronoun","reason":"An adverb describes how, when, or where an action happens. 'Her' describes who the face belongs to, not how the painting was done."},{"choice":"noun","category":"noun vs pronoun","reason":"A noun names a person, place, or thing. 'Her' is not the name of a person; it is a word used to point to someone already mentioned."},""]},"studyAid":{"definition":"A pronoun is a word used in place of a noun. Possessive pronouns like 'her', 'his', and 'my' show that someone owns or possesses something.","example":"Rachel used her brush (her = possessive pronoun); The book is his (his = possessive pronoun).","strategyClue":"Look at the word 'her' and ask, 'Is this a name, an action, or is it pointing to someone?' If it replaces a name or shows ownership, it falls into the pronoun category.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-authors-purpose","sourceFile":"Proficient-4_Informational Text.pdf","sourceQuestionNumber":6,"sourceCategory":"informational-text","sourceGrade":3,"sequence":200,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["reading-comprehension-authors-purpose"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["reading-comprehension-authors-purpose"] = chunkSet;
  }
})();
